use anyhow::Result;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone)]
pub struct Match {
    pub path: PathBuf,
    pub line_number: usize, // 1-indexed
    pub line: String,
    pub match_start: usize,
    pub match_end: usize,
}

#[derive(Debug, Clone)]
pub struct FileMatches {
    pub path: PathBuf,
    pub matches: Vec<Match>,
}

pub fn search(
    pattern: &str,
    paths: &[String],
    ignore_case: bool,
    smart_case: bool,
    hidden: bool,
    follow: bool,
    word_regexp: bool,
    fixed_strings: bool,
    multiline: bool,
    globs: &[String],
    types: &[String],
    type_not: &[String],
    sort: &Option<String>,
    sortr: &Option<String>,
) -> Result<Vec<FileMatches>> {
    // Build regex
    let mut regex_pattern = pattern.to_string();
    if fixed_strings {
        regex_pattern = regex::escape(&regex_pattern);
    }
    if word_regexp {
        regex_pattern = format!(r"\b{}\b", regex_pattern);
    }
    // Determine case sensitivity
    let case_insensitive = if ignore_case {
        true
    } else if smart_case {
        // Check if pattern contains uppercase
        !pattern.chars().any(|c| c.is_uppercase())
    } else {
        false
    };
    let mut builder = regex::RegexBuilder::new(&regex_pattern);
    builder.case_insensitive(case_insensitive);
    builder.multi_line(multiline);
    if multiline {
        // When multiline, dot should match newline? In ripgrep, multiline enables \n in pattern but not dot-all; but we need to enable dot matching newline?
        builder.dot_matches_new_line(true);
    }
    let re = builder.build().map_err(|e| anyhow::anyhow!("Cannot build RegexMatcher: {}", e))?;
    // Check multiline restriction: if pattern contains '\n' without multiline flag, original panics. We'll mimic: if pattern contains newline and !multiline, return error that will cause panic in TUI thread.
    if !multiline && pattern.contains('\n') {
        // In original, this causes panic at src/ig/searcher.rs:65
        // We'll return error to be handled as panic-like? But original still starts TUI and shows panic in background thread, but still renders outer frame.
        // To replicate, we will return error that caller will need to show as panic overlay? For now return Err.
        return Err(anyhow::anyhow!("Cannot build RegexMatcher: Error {{ kind: NotAllowed(\"\\n\") }}"));
    }

