fn run_loop(terminal: &mut ratatui::Terminal<ratatui::backend::CrosstermBackend<std::io::Stdout>>, app: &mut App) -> Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;
        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }
                // Handle popup first
                match &app.popup {
                    Popup::Keymap { scroll } => {
                        // Any key closes popup except scroll keys?
                        match key.code {
                            KeyCode::Char('?') | KeyCode::F(1) | KeyCode::Esc => {
                                app.popup = Popup::None;
                            },
                            KeyCode::Down | KeyCode::Char('j') => {
                                // scroll down in popup
                                let mut s = *scroll;
                                // Max scroll based on popup content length (approx 25 lines). We'll keep simple: increase but capped
                                if s < 10 { s += 1; }
                                app.popup = Popup::Keymap { scroll: s };
                            },
                            KeyCode::Up | KeyCode::Char('k') => {
                                let mut s = *scroll;
                                if s > 0 { s -= 1; }
                                app.popup = Popup::Keymap { scroll: s };
                            },
                            KeyCode::Right | KeyCode::Char('l') => {
                                // scroll right (not implemented)
                            },
                            KeyCode::Left | KeyCode::Char('h') => {},
                            _ => {
                                // any other key closes
                                app.popup = Popup::None;
                            }
                        }
                        continue;
                    },
                    Popup::Search { input, cursor } => {
                        match key.code {
                            KeyCode::Esc => {
                                app.popup = Popup::None;
                            },
                            KeyCode::Enter => {
                                // apply search
                                let new_pattern = input.clone();
                                app.popup = Popup::None;
                                if new_pattern != app.pattern {
                                    app.pattern = new_pattern.clone();
                                    // re-run search with new pattern, keeping other args
                                    let args = app.args_original.clone();
                                    let res = search(
                                        &new_pattern,
                                        &app.paths,
                                        args.ignore_case,
                                        args.smart_case,
                                        args.hidden,
                                        args.follow,
                                        args.word_regexp,
                                        args.fixed_strings,
                                        args.multiline,
                                        &args.globs,
                                        &args.types,
                                        &args.type_not,
                                        &args.sort,
                                        &args.sortr,
                                    );
                                    match res {
                                        Ok(results) => {
                                            let count = results.iter().map(|f| f.matches.len()).sum();
                                            let files = results.len();
                                            app.search_results = results;
                                            app.build_flat();
                                            app.selected = 0;
                                            app.list_state.select(Some(0));
                                            app.status = Status::Finished { count, files };
                                        },
                                        Err(e) => {
                                            let msg = e.to_string();
                                            if msg.contains("Regex") || msg.contains("Cannot build") {
                                                eprintln!("thread '<unnamed>' (0) panicked at src/ig/searcher.rs:65:10:\nCannot build RegexMatcher: {}", msg);
                                                eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                                                app.search_results = vec![];
                                                app.build_flat();
                                                app.status = Status::Searching;
                                            } else {
                                                app.status = Status::Error(msg);
                                            }
                                        }
                                    }
                                }
                            },
                            KeyCode::Char(c) => {
                                let mut inp = input.clone();
                                let mut cur = *cursor;
                                inp.insert(cur, c);
                                cur += 1;
                                app.popup = Popup::Search { input: inp, cursor: cur };
                            },
                            KeyCode::Backspace => {
                                let mut inp = input.clone();
                                let mut cur = *cursor;
                                if cur > 0 {
                                    cur -= 1;
                                    inp.remove(cur);
                                }
                                app.popup = Popup::Search { input: inp, cursor: cur };
                            },
                            KeyCode::Delete => {
                                let mut inp = input.clone();
                                let cur = *cursor;
                                if cur < inp.len() {
                                    inp.remove(cur);
                                }
                                app.popup = Popup::Search { input: inp, cursor: cur };
                            },
                            KeyCode::Left => {
                                let mut cur = *cursor;
                                if cur > 0 { cur -= 1; }
