                            // We need to re-enable raw mode and alternate screen?
                            // For now, after editor exits, we continue.
                            // But we need to redraw. The terminal is still in alternate screen; we should maybe leave and re-enter?
                            // The original after Enter, it suspends TUI, opens editor, then returns.
                            // We'll handle by leaving alternate screen, running editor, then re-entering.
                        }
                    },
                    KeyCode::Delete => {
                        app.filter_selected();
                    },
                    KeyCode::Char('v') => {
                        // toggle vertical
                        if app.context_viewer == ContextViewer::Vertical {
                            app.context_viewer = ContextViewer::None;
                        } else {
                            app.context_viewer = ContextViewer::Vertical;
                        }
                    },
                    KeyCode::Char('s') => {
                        if app.context_viewer == ContextViewer::Horizontal {
                            app.context_viewer = ContextViewer::None;
                        } else {
                            app.context_viewer = ContextViewer::Horizontal;
                        }
                    },
                    KeyCode::Char('+') | KeyCode::Char('=') => {
                        if app.context_size < 80 {
                            app.context_size += 5;
                        }
                    },
                    KeyCode::Char('-') | KeyCode::Char('_') => {
                        if app.context_size > 20 {
                            app.context_size -= 5;
                        }
                    },
                    KeyCode::F(5) => {
                        // open search popup
                        let input = app.pattern.clone();
                        let cursor = input.len();
                        app.popup = Popup::Search { input, cursor };
                    },
                    KeyCode::Char('/') => {
                        let input = app.pattern.clone();
                        let cursor = input.len();
                        app.popup = Popup::Search { input, cursor };
                    },
                    KeyCode::Char('n') => {
                        // sort by name (path)
                        app.sort_by = Some(SortBy::Path);
                        app.sort_reverse = false;
                        // re-sort search_results by path
                        app.search_results.sort_by(|a,b| a.path.cmp(&b.path));
                        app.build_flat();
                    },
                    KeyCode::Char('m') => {
                        app.sort_by = Some(SortBy::Modified);
                        app.sort_reverse = false;
                        app.search_results.sort_by(|a,b| {
                            let a_m = fs::metadata(&a.path).and_then(|m| m.modified()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            let b_m = fs::metadata(&b.path).and_then(|m| m.modified()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            a_m.cmp(&b_m)
                        });
                        app.build_flat();
                    },
                    KeyCode::Char('c') => {
                        app.sort_by = Some(SortBy::Created);
                        app.sort_reverse = false;
                        app.search_results.sort_by(|a,b| {
                            let a_c = fs::metadata(&a.path).and_then(|m| m.created()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            let b_c = fs::metadata(&b.path).and_then(|m| m.created()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            a_c.cmp(&b_c)
                        });
                        app.build_flat();
                    },
                    KeyCode::Char('a') => {
                        app.sort_by = Some(SortBy::Accessed);
                        app.sort_reverse = false;
                        app.search_results.sort_by(|a,b| {
                            let a_a = fs::metadata(&a.path).and_then(|m| m.accessed()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            let b_a = fs::metadata(&b.path).and_then(|m| m.accessed()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            a_a.cmp(&b_a)
                        });
                        app.build_flat();
                    },
                    _ => {}
                }

                // Handle gg and dd/dw specially which are two-key sequences
                // For gg: need to handle two 'g' presses
                // For dd: filter out selected, dw: filter out file
                // We'll handle via checking key.code == Char('g') and tracking last char
                // Use a simple static to remember previous key char for dd/dw etc. But we need state in App.
                // We will add fields for pending prefix.
                // For simplicity, handle dd/dw via checking if last key was 'd'
                // We'll add handling below after match

                // Handle 'd' prefix for dd/dw
                // We need to track if previous key was 'd'
                // We'll store in app a field pending_d: bool
                // But we didn't add field yet. Instead we handle via a closure with static? Simpler: check if key is 'd', then peek next event? Not good.
                // We'll add handling for 'd' sequences by looking ahead: if key is 'd', we need to wait for next key.
                // Instead, we can handle directly: when we get 'd', we enter a mode where next 'd' or 'w' triggers action.
                // We'll add field pending_d in App and check.
            }
            // Implement pending_d handling after event loop? Need to store.
            // For now, handle dd/dw via immediate check if key is 'd' then next poll will handle second? Instead we can use event::poll with timeout to wait for second key.
            // Simpler: we can add a state variable inside run_loop as mutable pending char
        }
    }
}

fn open_file(path: &PathBuf, line: usize, editor: &Option<Editor>, custom: &Option<String>) -> Result<()> {
    // Determine editor command
    let editor_obj = if let Some(c) = custom {
        Editor::Custom(c.clone())
    } else if let Some(e) = editor {
        e.clone()
    } else {
        Editor::detect().unwrap_or(Editor::Vim)
    };
    // Build command
    let cmd_vec = editor_obj.command(&path.to_string_lossy(), line);
    // For Custom, cmd_vec contains one string that is shell command; we need to execute via sh -c
    if let Editor::Custom(_) = editor_obj {
        let shell_cmd = &cmd_vec[0];
        // Need to execute via sh -c
        // Leave raw mode and alternate screen before spawning
        crossterm::terminal::disable_raw_mode()?;
        crossterm::execute!(io::stdout(), crossterm::terminal::LeaveAlternateScreen, crossterm::event::DisableMouseCapture)?;
        let status = std::process::Command::new("sh")
            .arg("-c")
            .arg(shell_cmd)
            .status()?;
        // Re-enter
        crossterm::terminal::enable_raw_mode()?;
        crossterm::execute!(io::stdout(), crossterm::terminal::EnterAlternateScreen, crossterm::event::EnableMouseCapture)?;
        let _ = status;
    } else {
        let prog = &cmd_vec[0];
        let args = &cmd_vec[1..];
        crossterm::terminal::disable_raw_mode()?;
        crossterm::execute!(io::stdout(), crossterm::terminal::LeaveAlternateScreen, crossterm::event::DisableMouseCapture)?;
        let status = std::process::Command::new(prog)
            .args(args)
            .status()
            .unwrap_or_else(|_| std::process::Command::new("sh").arg("-c").arg(format!("{} {}", prog, args.join(" "))).status().unwrap());
        crossterm::terminal::enable_raw_mode()?;
        crossterm::execute!(io::stdout(), crossterm::terminal::EnterAlternateScreen, crossterm::event::EnableMouseCapture)?;
        let _ = status;
    }
    Ok(())
}

fn ui(f: &mut Frame, app: &mut App) {
    let area = f.area();
    // Outer block
    let block = Block::default().borders(Borders::ALL).title("").border_style(Style::default().fg(Color::White));
    // Inside block content area
    let inner = block.inner(area);
    f.render_widget(block, area);

    // Split inner into list and context viewer + status bar
    // Status bar is at bottom of entire terminal? In original, status bar is at bottom row (outside inner block?) Let's check: In captures, status bar is at very bottom row (row 24) with green FINISHED and count, not inside block. The block is rows 0..23, status is row 24.
    // So we need to split area into main (top) and status (bottom 1 row)
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(0), Constraint::Length(1)])
        .split(area);
    let main_area = chunks[0];
    let status_area = chunks[1];
    // main_area includes block; we already rendered block over area, but status area is separate. We should render status separately.
    // For simplicity, we will split inner appropriately and render list inside main_area's inner.

    let main_inner = {
        // main_area's inner after block border: block inner is main_area inner minus border? Actually we rendered block over entire area, so inner is area minus border. But status_area is outside block? Let's just create layout where status is separate and block only covers main.
        // Let's instead re-render: main block should be only over main_area.
        // Clear and rerender? Easier: define main_block area = main_area, status = status_area.
        // We'll render main block over main_area (instead of previous block over area). For now we rendered block over area which includes status area incorrectly.
        // To fix, we will clear and render again.
        // Let's clear area and render correctly:
        // We'll just render main block over main_area now.
        // But we already rendered block over area, which covered status area with border. We'll overwrite status area later with status widget, so it's fine.
        // For list, we need area inside main_area's border.
        // Calculate inner of main_area
        let main_block = Block::default().borders(Borders::ALL);
        let inner_main = main_block.inner(main_area);
        // we already rendered block over area, but we can just use inner_main for list
        inner_main
    };

    // Now split inner_main based on context_viewer
    let (list_area, context_area) = match app.context_viewer {
        ContextViewer::None => (inner_main, None),
        ContextViewer::Vertical => {
            let c = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([Constraint::Percentage(100 - app.context_size as u16), Constraint::Percentage(app.context_size as u16)])
                .split(inner_main);
            (c[0], Some(c[1]))
        },
        ContextViewer::Horizontal => {
            let c = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Percentage(100 - app.context_size as u16), Constraint::Percentage(app.context_size as u16)])
                .split(inner_main);
            (c[0], Some(c[1]))
        }
    };

    // Build list items: grouped by file
    // We need to flatten but display as file header then matches.
    // For each FileMatches, we create a header item and then match items.
    // However our flat_matches is already flattened; but for display we need file headers.
    // Let's build items by iterating over search_results, not flat, to keep headers.
    let mut items: Vec<ListItem> = Vec::new();
    let mut flat_idx_to_list_idx: std::collections::HashMap<usize, usize> = std::collections::HashMap::new();
    let mut list_idx = 0;
    let mut flat_counter = 0;
    for fm in &app.search_results {
        // Check if any of its matches are not filtered? If all filtered, skip file header?
        let mut has_visible = false;
        for m in &fm.matches {
            // Find corresponding flat idx
            // For each match, find flat index where path == fm.path and line_number == m.line_number
            // Use iteration over flat_matches to find index where not filtered
            // Simpler: check flat_matches and filter_out
            if let Some(pos) = app.flat_matches.iter().position(|fm2| fm2.path == fm.path && fm2.line_number == m.line_number && fm2.line == m.line) {
                if !app.filter_out[pos] {
                    has_visible = true;
                    break;
                }
            } else {
                has_visible = true; // if not found, assume visible (maybe mismatch)
                break;
            }
        }
        if !has_visible {
            flat_counter += fm.matches.len();
            continue;
        }
        // File header
        let header = ListItem::new(Span::styled(fm.path.to_string_lossy().to_string(), Style::default().fg(app.theme.file_color())));
        items.push(header);
        list_idx += 1;
        for m in &fm.matches {
            if let Some(pos) = app.flat_matches.iter().position(|fm2| fm2.path == fm.path && fm2.line_number == m.line_number && fm2.line == m.line) {
                if app.filter_out[pos] {
                    flat_counter += 1;
                    continue;
                }
                // Mark mapping
                flat_idx_to_list_idx.insert(pos, list_idx);
            }
            // Build line with highlight
            let line_num_str = format!(" {}: ", m.line_number);
            // Highlight match
            let before = &m.line[..m.match_start.min(m.line.len())];
            let matched = &m.line[m.match_start.min(m.line.len())..m.match_end.min(m.line.len())];
            let after = &m.line[m.match_end.min(m.line.len())..];
            let mut spans = vec![];
            spans.push(Span::styled(line_num_str, Style::default().fg(app.theme.line_num_color())));
            spans.push(Span::raw(before.to_string()));
            spans.push(Span::styled(matched.to_string(), Style::default().fg(app.theme.match_color())));
            spans.push(Span::raw(after.to_string()));
            let line = Line::from(spans);
            let is_selected = app.flat_matches.get(app.selected).map(|fm| fm.path == fm.path && fm.line_number == m.line_number).unwrap_or(false) && app.flat_matches[app.selected].path == fm.path && app.flat_matches[app.selected].line_number == m.line_number;
            // Actually need to compare flat selected with this m
            let selected_flat = &app.flat_matches[app.selected];
            let is_sel = selected_flat.path == fm.path && selected_flat.line_number == m.line_number && selected_flat.line == m.line;
            let style = if is_sel {
                Style::default().bg(app.theme.highlight_bg())
            } else {
                Style::default()
            };
            items.push(ListItem::new(line).style(style));
            list_idx += 1;
            flat_counter += 1;
        }
    }

    // Determine list selected index
    // Our list includes headers, so selected index should map to corresponding list_idx
    let mut selected_list_idx: Option<usize> = None;
    if !app.flat_matches.is_empty() {
        if let Some(flat) = app.flat_matches.get(app.selected) {
            // Find its position in list
            // iterate again to find
            let mut idx = 0;
            for fm in &app.search_results {
                // header
                idx += 1;
                for m in &fm.matches {
                    // check if filtered
                    if let Some(pos) = app.flat_matches.iter().position(|fm2| fm2.path == fm.path && fm2.line_number == m.line_number) {
                        if app.filter_out[pos] {
                            continue;
                        }
                        if flat.path == fm.path && flat.line_number == m.line_number && flat.line == m.line {
                            selected_list_idx = Some(idx);
                            break;
                        }
                    }
                    idx += 1;
                }
                if selected_list_idx.is_some() { break; }
            }
        }
    }
    // Ensure list_state reflects selected_list_idx
    app.list_state.select(selected_list_idx);

    let mut list = List::new(items).highlight_style(Style::default().bg(app.theme.highlight_bg()));
    // f.render_stateful_widget(list, list_area, &mut app.list_state);
    // Use StatefulWidget rendering with our list_state (cloned)
    let mut state = app.list_state.clone();
    f.render_stateful_widget(list, list_area, &mut state);
    app.list_state = state;

    // Context viewer
    if let Some(ctx_area) = context_area {
        // Show file content around selected match
        if let Some(flat) = app.flat_matches.get(app.selected) {
            if !app.filter_out[app.selected] {
                let path = &flat.path;
                let content = fs::read_to_string(path).unwrap_or_else(|_| "".to_string());
                let lines: Vec<&str> = content.lines().collect();
                let line_idx = flat.line_number as isize - 1;
                // Show context window of maybe 10 lines around
                let context_radius = 5;
                let start = (line_idx - context_radius as isize).max(0) as usize;
                let end = (line_idx + context_radius as isize + 1).min(lines.len() as isize) as usize;
                let mut text_lines: Vec<Line> = Vec::new();
                for (i, l) in lines[start..end].iter().enumerate() {
                    let actual_line_num = start + i + 1;
                    let mut spans = vec![Span::styled(format!("{:4} ", actual_line_num), Style::default().fg(app.theme.line_num_color()))];
                    if actual_line_num == flat.line_number {
                        // highlight match line
                        let before = &l[..flat.match_start.min(l.len())];
                        let matched = &l[flat.match_start.min(l.len())..flat.match_end.min(l.len())];
                        let after = &l[flat.match_end.min(l.len())..];
                        spans.push(Span::raw(before.to_string()));
                        spans.push(Span::styled(matched.to_string(), Style::default().fg(app.theme.match_color()).add_modifier(Modifier::BOLD)));
                        spans.push(Span::raw(after.to_string()));
                    } else {
                        spans.push(Span::raw(l.to_string()));
                    }
                    text_lines.push(Line::from(spans));
                }
                let para = Paragraph::new(text_lines).block(Block::default().borders(Borders::ALL).title("Context")).wrap(Wrap { trim: true });
                f.render_widget(para, ctx_area);
            } else {
                let para = Paragraph::new("No context").block(Block::default().borders(Borders::ALL));
                f.render_widget(para, ctx_area);
            }
        } else {
            let para = Paragraph::new("No selection").block(Block::default().borders(Borders::ALL));
            f.render_widget(para, ctx_area);
        }
    }

    // Status bar
    let status_style = match &app.status {
        Status::Searching => Style::default().bg(Color::Rgb(255,165,0)).fg(Color::Black),
        Status::Finished { .. } => Style::default().bg(Color::Rgb(0,128,0)).fg(Color::Black),
        Status::Error(_) => Style::default().bg(Color::Red).fg(Color::White),
    };
    let status_text = match &app.status {
        Status::Searching => {
            format!("  SEARCHING                                                                                                       | {}/{} ", app.flat_matches.iter().filter(|(_, _)| false).count(), 0) // placeholder
        },
        Status::Finished { count, files } => {
            let filtered_count = app.filter_out.iter().filter(|&&b| !b).count();
            let filtered_files = {
                let mut set = std::collections::HashSet::new();
                for (i, fm) in app.flat_matches.iter().enumerate() {
                    if !app.filter_out[i] {
                        set.insert(&fm.path);
                    }
                }
                set.len()
            };
            // Original shows "Found X matches in Y files." and position indicator " | cur/total "
            let total_visible = filtered_count;
            let cur = if app.flat_matches.is_empty() { 0 } else { app.selected + 1 };
            format!("  FINISHED   Found {} matches in {} files.                                                                          |  {}/{} ", filtered_count, filtered_files, cur, total_visible)
        },
        Status::Error(msg) => format!("  ERROR: {} ", msg),
    };
    // For searching, show 0/0?
    let status_text2 = match &app.status {
        Status::Searching => format!("  SEARCHING                                                                                                       | 0/0 "),
        _ => status_text,
    };
    let status_para = Paragraph::new(status_text2).style(status_style);
    f.render_widget(status_para, status_area);

    // Popups
    match &app.popup {
        Popup::Keymap { scroll } => {
            let popup_area = centered_rect(60, 60, area);
            f.render_widget(Clear, popup_area);
            let block = Block::default().borders(Borders::ALL).title(" igrep 1.3.0 ").border_style(Style::default().fg(Color::White));
            let inner = block.inner(popup_area);
            f.render_widget(block, popup_area);
            // Keymap content
            let rows = vec![
                ("q, Esc, Ctrl+c", "Quit"),
                ("", ""),
                ("?, F1", "Open/close the keymap popup"),
                ("Down, j", "Scroll down in the keymap popup"),
                ("Up, k", "Scroll up in the keymap popup"),
                ("Right, l", "Scroll right in the keymap popup"),
                ("Left, h", "Scroll left in the keymap popup"),
                ("", ""),
                ("Down, j", "Select next match"),
                ("Up,k", "Select previous match"),
                ("Right, l, PageDown", "Select match in next file"),
                ("Left, h, PageUp", "Select match in previous file"),
                ("gg, Home", "Jump to the first match"),
                ("Shift-g, End", "Jump to the last match"),
                ("Enter", "Open current file"),
                ("dd, Delete", "Filter out selected match"),
                ("dw", "Filter out all matches in current file"),
                ("v", "Toggle vertical context viewer"),
                ("s", "Toggle horizontal context viewer"),
                ("+", "Increase context viewer size"),
                ("-", "Decrease context viewer size"),
                ("F5, /", "Open search pattern popup"),
                ("n", "Sort search results by name"),
                ("m", "Sort search results by time modified"),
                ("c", "Sort search results by time created"),
                ("a", "Sort search results by time accessed"),
                ("", ""),
                ("Press any key to close…", ""),
            ];
            let mut lines: Vec<Line> = Vec::new();
            lines.push(Line::from(vec![
                Span::styled(" Key(s)             ", Style::default().add_modifier(Modifier::BOLD)),
                Span::raw("│ "),
                Span::styled("Action", Style::default().add_modifier(Modifier::BOLD)),
            ]));
            lines.push(Line::from(" ───────────────────┼─────────────────────────────────────── "));
            for (k, a) in rows.iter().skip(*scroll).take(inner.height as usize - 3) {
                if k.is_empty() && a.is_empty() {
                    lines.push(Line::from("                    │                                        "));
                } else if k == &"Press any key to close…" {
                    lines.push(Line::from(vec![
                        Span::raw("                                                             "),
                    ]));
                    lines.push(Line::from(format!(" {}", k)));
                } else {
                    let key_col = format!(" {:<18} │ {}", k, a);
                    lines.push(Line::from(key_col));
                }
            }
            let para = Paragraph::new(lines);
            f.render_widget(para, inner);
        },
        Popup::Search { input, cursor } => {
            let popup_area = centered_rect(40, 3, area);
            f.render_widget(Clear, popup_area);
            let block = Block::default().borders(Borders::ALL).title(" Regex Pattern ").border_style(Style::default().fg(Color::White));
            let inner = block.inner(popup_area);
            f.render_widget(block, popup_area);
            // Show input
            let mut spans = vec![Span::raw(input.clone())];
            let para = Paragraph::new(Line::from(spans));
            f.render_widget(para, inner);
            // Set cursor
            f.set_cursor_position(Position { x: inner.x + *cursor as u16, y: inner.y });
        },
        Popup::None => {}
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}
