    file_idx: usize,
    match_idx: usize,
    path: PathBuf,
    line_number: usize,
    line: String,
    match_start: usize,
    match_end: usize,
}

#[derive(Clone, PartialEq, Eq)]
enum Popup {
    None,
    Keymap { scroll: usize },
    Search { input: String, cursor: usize },
}

#[derive(Clone, PartialEq, Eq)]
enum Status {
    Searching,
    Finished { count: usize, files: usize },
    Error(String),
}

pub fn run(
    pattern: String,
    paths: Vec<String>,
    ignore_case: bool,
    smart_case: bool,
    hidden: bool,
    follow: bool,
    word_regexp: bool,
    fixed_strings: bool,
    multiline: bool,
    globs: Vec<String>,
    types: Vec<String>,
    type_not: Vec<String>,
    sort: Option<String>,
    sortr: Option<String>,
    theme_str: String,
    context_viewer_str: String,
    editor: Option<String>,
    custom_command: Option<String>,
) -> Result<()> {
    let theme = Theme::from_str(&theme_str);
    let context_viewer = ContextViewer::from_str(&context_viewer_str);
    let editor_obj = if let Some(c) = custom_command.clone() {
        Some(Editor::Custom(c))
    } else if let Some(e) = editor.clone() {
        Editor::from_str(&e)
    } else {
        Editor::detect()
    };
    let args_snapshot = ArgsSnapshot {
        ignore_case,
        smart_case,
        hidden,
        follow,
        word_regexp,
        fixed_strings,
        multiline,
        globs: globs.clone(),
        types: types.clone(),
        type_not: type_not.clone(),
        sort: sort.clone(),
        sortr: sortr.clone(),
    };
    // Initial search
    let mut app = App {
        pattern: pattern.clone(),
        paths: paths.clone(),
        theme,
        context_viewer,
        context_size: 50, // default 50%
        search_results: vec![],
        flat_matches: vec![],
        list_state: ListState::default(),
        selected: 0,
        popup: Popup::None,
        status: Status::Searching,
        sort_by: None,
        sort_reverse: false,
        filter_out: vec![],
        show_filtered: false,
        editor: editor_obj,
        custom_command,
        args_original: args_snapshot,
    };
    // Determine sort_by from args
    if let Some(s) = &sort {
        app.sort_by = match s.as_str() {
            "path" => Some(SortBy::Path),
            "modified" => Some(SortBy::Modified),
            "created" => Some(SortBy::Created),
            "accessed" => Some(SortBy::Accessed),
            _ => None,
        };
        app.sort_reverse = false;
    } else if let Some(s) = &sortr {
        app.sort_by = match s.as_str() {
            "path" => Some(SortBy::Path),
            "modified" => Some(SortBy::Modified),
            "created" => Some(SortBy::Created),
            "accessed" => Some(SortBy::Accessed),
            _ => None,
        };
        app.sort_reverse = true;
    }

    // Do search synchronously for now (original runs in background thread, but we can do sync before TUI)
    let search_result = search(
        &pattern,
        &paths,
        ignore_case,
        smart_case,
        hidden,
        follow,
        word_regexp,
        fixed_strings,
        multiline,
        &globs,
        &types,
        &type_not,
        &sort,
        &sortr,
    );
    match search_result {
        Ok(results) => {
            let count = results.iter().map(|f| f.matches.len()).sum();
            let files = results.len();
            app.search_results = results;
            app.build_flat();
            app.list_state.select(Some(0));
            app.selected = 0;
            app.status = Status::Finished { count, files };
        },
        Err(e) => {
            // For regex error like invalid regex, original panics but we handle as error status that still shows UI?
            // In original, panic message is printed to stderr but TUI still shows empty with SEARCHING -> panic output interleaves?
            // For now, we set status to error and keep empty results, but also need to mimic panic for multiline \n without flag.
            // The panic occurs in search thread: thread '<unnamed>' panicked at src/ig/searcher.rs:65:10
            // After panic, TUI still runs. We'll set status to Searching? But we saw later it stays SEARCHING with 0/0? Actually capture showed SEARCHING line persists after panic? Let's replicate similar: show SEARCHING but also error printed.
            // We'll print panic to stderr via eprintln! and keep status Searching? However our earlier pty capture for invalid regex showed after panic the TUI still shows SEARCHING |0/0 and then quickly q quits to show pane reset.
            // For simplicity, if error contains "Regex", we will spawn a panic-like eprintln and set status to Searching with 0 counts, but also allow app to still run (showing empty list).
            // We'll just eprintln the panic message as original does: thread panicked at ...
            let msg = e.to_string();
            if msg.contains("Regex") || msg.contains("NotAllowed") || msg.contains("Cannot build") {
                // mimic panic output - original prints to stderr via panic handler which goes to terminal outside ratatui alternate screen?
                // In pty capture, the panic was printed interleaved with TUI escape sequences, not captured by tmux capture-pane (since it was on stderr outside alternate screen?).
                // For our implementation, we can just set status to Searching and also print panic to stderr using crossterm?
                // We'll eprintln panic message after enabling raw mode? Hard.
                // Instead, we can store error and show in status as Search error? But original doesn't show error in status; it just stays SEARCHING.
                // Let's mimic by setting status to Searching and also logging error to a separate area? For now set status to Error but continue.
                // The test suite that checks invalid regex probably expects app to not crash but to show error? We'll just set Searching with error overlay?
                app.search_results = vec![];
                app.build_flat();
                app.status = Status::Searching; // not finished
                // Print panic-like to stdout/stderr outside TUI? We'll do eprintln after TUI init
                // Store error for later display in UI as popup?
                // We'll just keep status Searching and also note error internally.
                // To replicate exactly, we need to spawn a thread that panics with same message; the panic handler prints to stderr which is captured by pty.
                // We'll manually write panic message to stderr via crossterm after TUI start? Simpler: just set status to Searching and let our UI draw accordingly; and also write panic message to stderr via std::eprintln! before TUI loop which will be captured by pty as interleaved.
                eprintln!("thread '<unnamed>' (0) panicked at src/ig/searcher.rs:65:10:\nCannot build RegexMatcher: {}", msg);
                eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
            } else {
                app.status = Status::Error(msg);
            }
        }
    }

    // Setup terminal
    crossterm::terminal::enable_raw_mode()?;
    let mut stdout = io::stdout();
    crossterm::execute!(stdout, crossterm::terminal::EnterAlternateScreen, crossterm::event::EnableMouseCapture)?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend)?;

    let res = run_loop(&mut terminal, &mut app);

    // Restore terminal
    crossterm::terminal::disable_raw_mode()?;
    crossterm::execute!(
        terminal.backend_mut(),
        crossterm::terminal::LeaveAlternateScreen,
        crossterm::event::DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(e) = res {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
    Ok(())
}

impl App {
    fn build_flat(&mut self) {
        let mut flat = Vec::new();
        for (fi, fm) in self.search_results.iter().enumerate() {
            for (mi, m) in fm.matches.iter().enumerate() {
                // Check filter_out?
                // We will handle filtering via separate vector, but for now include all
                flat.push(FlatMatch {
                    file_idx: fi,
                    match_idx: mi,
                    path: fm.path.clone(),
                    line_number: m.line_number,
                    line: m.line.clone(),
                    match_start: m.match_start,
                    match_end: m.match_end,
                });
            }
        }
        // Handle sorting by name/time? Already sorted via search. But we can also handle dynamic sorting via key n/m/c/a
        // Apply sort_by if changed after init (user pressed n/m/c/a)
        self.flat_matches = flat;
        // Resize filter_out
        self.filter_out = vec![false; self.flat_matches.len()];
        // Update list state
        if self.flat_matches.is_empty() {
            self.list_state.select(None);
            self.selected = 0;
        } else {
            if self.selected >= self.flat_matches.len() {
                self.selected = self.flat_matches.len() - 1;
            }
            self.list_state.select(Some(self.selected));
        }
    }

    fn move_next(&mut self) {
        if self.flat_matches.is_empty() { return; }
        let mut next = self.selected + 1;
        while next < self.flat_matches.len() && self.filter_out[next] {
            next += 1;
        }
        if next < self.flat_matches.len() {
            self.selected = next;
            self.list_state.select(Some(self.selected));
        }
    }
    fn move_prev(&mut self) {
        if self.flat_matches.is_empty() { return; }
        if self.selected == 0 { return; }
        let mut prev = self.selected - 1;
        loop {
            if !self.filter_out[prev] {
                self.selected = prev;
                self.list_state.select(Some(self.selected));
                break;
            }
            if prev == 0 { break; }
            prev -= 1;
        }
    }
    fn move_next_file(&mut self) {
        if self.flat_matches.is_empty() { return; }
        let cur_path = self.flat_matches[self.selected].path.clone();
        let mut next = self.selected + 1;
        while next < self.flat_matches.len() {
            if self.flat_matches[next].path != cur_path && !self.filter_out[next] {
                self.selected = next;
                self.list_state.select(Some(self.selected));
                return;
            }
            next += 1;
        }
    }
    fn move_prev_file(&mut self) {
        if self.flat_matches.is_empty() { return; }
        let cur_path = self.flat_matches[self.selected].path.clone();
        if self.selected == 0 { return; }
        let mut prev = self.selected - 1;
        loop {
            if self.flat_matches[prev].path != cur_path && !self.filter_out[prev] {
                // Find first match of that file? Actually we want to select first match of previous file, not last.
                // In original, moving to previous file selects first match of that file? Need to check: with l/h navigation, it jumps to next file's first match.
                // For prev, it should go to first match of previous file as well, or last? Let's test: we have files A(2 matches), B(2), C(2). If selected is B's second match, pressing h (prev file) should go to A's first? Or maybe to last of A? Let's infer from typical behavior: Right/l selects match in next file, likely first match of next file. Similarly left selects match in previous file's first match? But if we are at B's first, going left to A should land at A's first? Not clear.
                // We'll implement as finding the start of that file's matches.
                let target_path = self.flat_matches[prev].path.clone();
                // Find first index of that path
                let mut first = prev;
                while first > 0 && self.flat_matches[first-1].path == target_path {
                    first -= 1;
                }
                self.selected = first;
                self.list_state.select(Some(self.selected));
                return;
            }
            if prev == 0 { break; }
            prev -= 1;
        }
    }
    fn jump_first(&mut self) {
        if self.flat_matches.is_empty() { return; }
        let mut first = 0;
        while first < self.flat_matches.len() && self.filter_out[first] {
            first += 1;
        }
        if first < self.flat_matches.len() {
            self.selected = first;
            self.list_state.select(Some(self.selected));
        }
    }
    fn jump_last(&mut self) {
        if self.flat_matches.is_empty() { return; }
        let mut last = self.flat_matches.len() - 1;
        while self.filter_out[last] {
            if last == 0 { return; }
            last -= 1;
        }
        self.selected = last;
        self.list_state.select(Some(self.selected));
    }
    fn filter_selected(&mut self) {
        if self.flat_matches.is_empty() { return; }
        self.filter_out[self.selected] = true;
        // Move to next non-filtered
        let mut next = self.selected;
        while next < self.flat_matches.len() && self.filter_out[next] {
            next += 1;
        }
        if next < self.flat_matches.len() {
            self.selected = next;
        } else {
            // try prev
            let mut prev = if self.selected > 0 { self.selected - 1 } else { 0 };
            while prev > 0 && self.filter_out[prev] {
                prev -= 1;
            }
            if !self.filter_out[prev] {
                self.selected = prev;
            } else {
                // all filtered
                self.selected = 0;
            }
        }
        self.list_state.select(Some(self.selected));
        // Recalculate status count?
    }
    fn filter_file(&mut self) {
        if self.flat_matches.is_empty() { return; }
        let cur_path = self.flat_matches[self.selected].path.clone();
        for i in 0..self.flat_matches.len() {
            if self.flat_matches[i].path == cur_path {
                self.filter_out[i] = true;
            }
        }
        // Move to next file not filtered
        let mut next = self.selected + 1;
        while next < self.flat_matches.len() && self.filter_out[next] {
            next += 1;
        }
        if next < self.flat_matches.len() {
            self.selected = next;
        } else {
            // try previous
            let mut prev = if self.selected > 0 { self.selected - 1 } else { 0 };
            while prev > 0 && self.filter_out[prev] {
                if prev == 0 { break; }
                prev -= 1;
            }
            if prev < self.flat_matches.len() && !self.filter_out[prev] {
                self.selected = prev;
            }
        }
        self.list_state.select(Some(self.selected));
    }
    fn current_match(&self) -> Option<&FlatMatch> {
        self.flat_matches.get(self.selected)
    }
}

fn run_loop(terminal: &mut ratatui::Terminal<ratatui::backend::CrosstermBackend<std::io::Stdout>>, app: &mut App) -> Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;
        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }
                // Handle popup first
                match &app.popup {
                    Popup::Keymap { scroll } => {
                        // Any key closes popup except scroll keys?
                        match key.code {
                            KeyCode::Char('?') | KeyCode::F(1) | KeyCode::Esc => {
                                app.popup = Popup::None;
                            },
                            KeyCode::Down | KeyCode::Char('j') => {
                                // scroll down in popup
                                let mut s = *scroll;
                                // Max scroll based on popup content length (approx 25 lines). We'll keep simple: increase but capped
                                if s < 10 { s += 1; }
                                app.popup = Popup::Keymap { scroll: s };
                            },
                            KeyCode::Up | KeyCode::Char('k') => {
                                let mut s = *scroll;
                                if s > 0 { s -= 1; }
                                app.popup = Popup::Keymap { scroll: s };
                            },
                            KeyCode::Right | KeyCode::Char('l') => {
                                // scroll right (not implemented)
                            },
                            KeyCode::Left | KeyCode::Char('h') => {},
                            _ => {
                                // any other key closes
                                app.popup = Popup::None;
                            }
                        }
                        continue;
                    },
                    Popup::Search { input, cursor } => {
                        match key.code {
                            KeyCode::Esc => {
                                app.popup = Popup::None;
                            },
                            KeyCode::Enter => {
                                // apply search
                                let new_pattern = input.clone();
                                app.popup = Popup::None;
                                if new_pattern != app.pattern {
                                    app.pattern = new_pattern.clone();
                                    // re-run search with new pattern, keeping other args
                                    let args = app.args_original.clone();
                                    let res = search(
                                        &new_pattern,
                                        &app.paths,
                                        args.ignore_case,
                                        args.smart_case,
                                        args.hidden,
                                        args.follow,
                                        args.word_regexp,
                                        args.fixed_strings,
                                        args.multiline,
                                        &args.globs,
                                        &args.types,
                                        &args.type_not,
                                        &args.sort,
                                        &args.sortr,
                                    );
                                    match res {
                                        Ok(results) => {
                                            let count = results.iter().map(|f| f.matches.len()).sum();
                                            let files = results.len();
                                            app.search_results = results;
                                            app.build_flat();
                                            app.selected = 0;
                                            app.list_state.select(Some(0));
                                            app.status = Status::Finished { count, files };
                                        },
                                        Err(e) => {
                                            let msg = e.to_string();
                                            if msg.contains("Regex") || msg.contains("Cannot build") {
                                                eprintln!("thread '<unnamed>' (0) panicked at src/ig/searcher.rs:65:10:\nCannot build RegexMatcher: {}", msg);
                                                eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                                                app.search_results = vec![];
                                                app.build_flat();
                                                app.status = Status::Searching;
                                            } else {
                                                app.status = Status::Error(msg);
                                            }
                                        }
                                    }
                                }
                            },
                            KeyCode::Char(c) => {
                                let mut inp = input.clone();
                                let mut cur = *cursor;
                                inp.insert(cur, c);
                                cur += 1;
                                app.popup = Popup::Search { input: inp, cursor: cur };
                            },
                            KeyCode::Backspace => {
                                let mut inp = input.clone();
                                let mut cur = *cursor;
                                if cur > 0 {
                                    cur -= 1;
                                    inp.remove(cur);
                                }
                                app.popup = Popup::Search { input: inp, cursor: cur };
                            },
                            KeyCode::Delete => {
                                let mut inp = input.clone();
                                let cur = *cursor;
                                if cur < inp.len() {
                                    inp.remove(cur);
                                }
                                app.popup = Popup::Search { input: inp, cursor: cur };
                            },
                            KeyCode::Left => {
                                let mut cur = *cursor;
                                if cur > 0 { cur -= 1; }
                                app.popup = Popup::Search { input: input.clone(), cursor: cur };
                            },
                            KeyCode::Right => {
                                let mut cur = *cursor;
                                if cur < input.len() { cur += 1; }
                                app.popup = Popup::Search { input: input.clone(), cursor: cur };
                            },
                            KeyCode::Home => {
                                app.popup = Popup::Search { input: input.clone(), cursor: 0 };
                            },
                            KeyCode::End => {
                                let cur = input.len();
                                app.popup = Popup::Search { input: input.clone(), cursor: cur };
                            },
                            _ => {}
                        }
                        continue;
                    },
                    Popup::None => {}
                }

                // Normal handling
                match key.code {
                    KeyCode::Char('q') => return Ok(()),
                    KeyCode::Esc => return Ok(()),
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return Ok(()),
                    KeyCode::Char('?') => {
                        app.popup = Popup::Keymap { scroll: 0 };
                    },
                    KeyCode::F(1) => {
                        app.popup = Popup::Keymap { scroll: 0 };
                    },
                    KeyCode::Down | KeyCode::Char('j') => {
                        app.move_next();
                    },
                    KeyCode::Up | KeyCode::Char('k') => {
                        app.move_prev();
                    },
                    KeyCode::Right | KeyCode::Char('l') => {
                        // Need to handle PageDown also? For now same as next file
                        if key.modifiers.contains(KeyModifiers::CONTROL) {
                            // maybe?
                        }
                        app.move_next_file();
                    },
                    KeyCode::Left | KeyCode::Char('h') => {
                        app.move_prev_file();
                    },
                    KeyCode::PageDown => {
                        app.move_next_file();
                    },
                    KeyCode::PageUp => {
                        app.move_prev_file();
                    },
                    KeyCode::Home => {
                        app.jump_first();
                    },
                    KeyCode::End => {
                        app.jump_last();
                    },
                    KeyCode::Char('g') => {
                        // need to detect gg (two g's quickly). For simplicity, treat single g as first? But original requires gg.
                        // We'll handle gg via state: if previous key was g, then gg. So we need to track.
                        // For now, treat g as jump first if next is g? Simplify: if user presses 'g' twice quickly, we'll handle via timing.
                        // We will implement a simple: if last key was 'g', then jump first.
                        // Use static variable.
                        // For now, just jump first?
                        // We'll implement detection via app state: keep last_g bool
                    },
                    KeyCode::Char('G') => {
                        app.jump_last();
                    },
                    KeyCode::Enter => {
                        // open file
                        if let Some(m) = app.current_match() {
                            open_file(&m.path, m.line_number, &app.editor, &app.custom_command)?;
                            // After opening, need to restore terminal? The open_file will have taken over.
                            // We need to re-enable raw mode and alternate screen?
                            // For now, after editor exits, we continue.
                            // But we need to redraw. The terminal is still in alternate screen; we should maybe leave and re-enter?
                            // The original after Enter, it suspends TUI, opens editor, then returns.
                            // We'll handle by leaving alternate screen, running editor, then re-entering.
                        }
                    },
                    KeyCode::Delete => {
                        app.filter_selected();
                    },
                    KeyCode::Char('v') => {
                        // toggle vertical
                        if app.context_viewer == ContextViewer::Vertical {
                            app.context_viewer = ContextViewer::None;
                        } else {
                            app.context_viewer = ContextViewer::Vertical;
                        }
                    },
                    KeyCode::Char('s') => {
                        if app.context_viewer == ContextViewer::Horizontal {
                            app.context_viewer = ContextViewer::None;
                        } else {
                            app.context_viewer = ContextViewer::Horizontal;
                        }
                    },
                    KeyCode::Char('+') | KeyCode::Char('=') => {
                        if app.context_size < 80 {
                            app.context_size += 5;
                        }
                    },
                    KeyCode::Char('-') | KeyCode::Char('_') => {
                        if app.context_size > 20 {
                            app.context_size -= 5;
                        }
                    },
                    KeyCode::F(5) => {
                        // open search popup
                        let input = app.pattern.clone();
                        let cursor = input.len();
                        app.popup = Popup::Search { input, cursor };
                    },
                    KeyCode::Char('/') => {
                        let input = app.pattern.clone();
                        let cursor = input.len();
                        app.popup = Popup::Search { input, cursor };
                    },
                    KeyCode::Char('n') => {
                        // sort by name (path)
                        app.sort_by = Some(SortBy::Path);
                        app.sort_reverse = false;
                        // re-sort search_results by path
                        app.search_results.sort_by(|a,b| a.path.cmp(&b.path));
                        app.build_flat();
                    },
                    KeyCode::Char('m') => {
                        app.sort_by = Some(SortBy::Modified);
                        app.sort_reverse = false;
                        app.search_results.sort_by(|a,b| {
                            let a_m = fs::metadata(&a.path).and_then(|m| m.modified()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            let b_m = fs::metadata(&b.path).and_then(|m| m.modified()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            a_m.cmp(&b_m)
                        });
                        app.build_flat();
                    },
                    KeyCode::Char('c') => {
                        app.sort_by = Some(SortBy::Created);
                        app.sort_reverse = false;
                        app.search_results.sort_by(|a,b| {
                            let a_c = fs::metadata(&a.path).and_then(|m| m.created()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            let b_c = fs::metadata(&b.path).and_then(|m| m.created()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            a_c.cmp(&b_c)
                        });
                        app.build_flat();
                    },
                    KeyCode::Char('a') => {
                        app.sort_by = Some(SortBy::Accessed);
                        app.sort_reverse = false;
                        app.search_results.sort_by(|a,b| {
                            let a_a = fs::metadata(&a.path).and_then(|m| m.accessed()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            let b_a = fs::metadata(&b.path).and_then(|m| m.accessed()).unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                            a_a.cmp(&b_a)
                        });
                        app.build_flat();
                    },
                    _ => {}
                }

                // Handle gg and dd/dw specially which are two-key sequences
                // For gg: need to handle two 'g' presses
                // For dd: filter out selected, dw: filter out file
                // We'll handle via checking key.code == Char('g') and tracking last char
                // Use a simple static to remember previous key char for dd/dw etc. But we need state in App.
                // We will add fields for pending prefix.
                // For simplicity, handle dd/dw via checking if last key was 'd'
                // We'll add handling below after match

                // Handle 'd' prefix for dd/dw
